import sys, json
from html.parser import HTMLParser

class TextExtract(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.skip = 0
    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip:
            self.skip -= 1
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

doc = json.load(sys.stdin)
d = doc["body"]
envelope = doc["envelope"]
ctx = envelope.get("header", {}).get("context", {})

body_text = ""
for m in d.get("messages", []):
    if m.get("type") == "tool_result":
        body_text = m.get("text", "")
        break

if "<" in body_text:
    p = TextExtract()
    try:
        p.feed(body_text)
        p.close()
        body_text = " ".join(p.parts)
    except Exception:
        pass
body_text = " ".join(body_text.split())

excerpt = body_text[:3500]
if len(body_text) > 3500:
    excerpt += "\n[truncated]"

try:
    chat_id = int(str(ctx.get("chat_id", "0")))
except ValueError:
    chat_id = 0

out = {
    "header": { "chat_id": chat_id },
    "messages": [
        { "origin": "assistant", "type": "text", "text": "Daily digest:\n" + excerpt }
    ]
}
sys.stdout.write(json.dumps(out))
